import { createSlice } from '@reduxjs/toolkit';
import { getListDepositAccounts } from './thunk';
import type { IAccount } from '@src/domain/entities/loan_collateral/depositAccount';

interface IState {
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string;
    amount: number;
    systemDate: string;
    accounts: IAccount[] | undefined;
}

const initialState: IState = {
    status: 'idle',
    error: '',
    amount: 0,
    systemDate: '',
    accounts: [],
};

const slice = createSlice({
    name: 'loan_collateral_amount',
    initialState,
    reducers: {
        setStatus: (state, { payload }) => {
            state.status = payload;
        },
        setError: (state, { payload }) => {
            state.error = payload;
        },
        setAmount: (state, { payload }) => {
            state.amount = payload;
        },
        setAccountList: (state, { payload }) => {
            state.accounts = payload;
        },
        resetAccounts: (state) => {
            state.accounts = [];
            state.error = '';
        },
    },
    extraReducers: (builder) => {
        builder
            .addCase(getListDepositAccounts.pending, (state, action) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(getListDepositAccounts.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message || 'error fetch getListDepositAccounts';
            })
            .addCase(getListDepositAccounts.fulfilled, (state, { payload }) => {
                state.status = 'succeeded';
                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00' && data) {
                    state.accounts = data.accounts.map((item) => ({
                        ...item,
                        intRate: Number(item.intRate).toFixed(2),
                    }));
                    state.error = '';
                    state.systemDate = data.systemDate;
                } else {
                    state.error = resultMessage;
                }
            });
    },
});

export default slice;
