import React, { useCallback, useEffect, useState } from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground, Alert, KeyboardAvoidingView } from 'react-native';
import { GradientButton, LoadingBlockerView, SimpleHeader, Spacer, Text } from '@core/ui';
import useCSS from '@src/presentation/style';

import { CURRENCY } from '@src/utils/constants';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import CurrencyInput from './components/CurrencyInput';
import confirmSlice from '@src/presentation/loan_collateral/collateral_confirm/slice';
import { useDispatch, useSelector } from '@src/lib/redux';
import {
    selectAccount,
    selectAvailableOutstanding,
    selectError,
    selectIsCounter,
    selectMaxAmount,
    selectMinAmount,
    selectProductCode,
    selectProductStatus,
    selectResultCodeProductStatus,
    selectStatus,
    selectStatusProductStatus,
} from '../collateral_confirm/selector';
import { formatMoney } from '@src/utils/currency';
import { useTranslation } from 'react-i18next';
import { fetchGetInitLoanProposal } from '../collateral_confirm/thunk';
import type { GetInitLoanProposalPayload } from '@src/application/loan_collateral/queries/get_init_loan_proposal/get_init_loan_proposal_query';
import { fetchProductStatus } from '@src/presentation/loan_collateral/collateral_confirm/thunk';
import { ProductStatusPayload } from '@src/application/loan_product/queries/get_product_status/get_product_status_query';
import { selectClientNo } from '@src/presentation/loan_products/selector';
import getImg from '@src/utils/getImg';
import slice from './slice';
import { IS_IOS } from '@core/service';

const CollateralAmountScreen = () => {
    const css = useCSS();
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['module_collateral']);

    const clientNo = useSelector(selectClientNo);
    const status = useSelector(selectStatus);
    const error = useSelector(selectError);

    const productCode = useSelector(selectProductCode);
    const account = useSelector(selectAccount);
    const minAmount = useSelector(selectMinAmount);
    const maxAmount = useSelector(selectMaxAmount);
    const resultCodeProductStatus = useSelector(selectResultCodeProductStatus);
    const statusProductStatus = useSelector(selectStatusProductStatus);
    const productStatus = useSelector(selectProductStatus);
    const isCounter = useSelector(selectIsCounter);
    const availableOutstanding = useSelector(selectAvailableOutstanding);

    const [amount, setAmount] = useState(0);

    const [disabled, setDisabled] = useState(true);

    const handleAmount = useCallback(
        (num: number) => {
            setAmount(num);
            if (num <= Number(maxAmount) && num >= Number(minAmount)) {
                setDisabled(false);
            } else {
                setDisabled(true);
            }
        },
        [amount],
    );

    const handleSubmit = () => {
        if (!disabled) {
            dispatch(confirmSlice.actions.setLoanAmount(amount));

            if (isCounter === false && Number(amount) > Number(availableOutstanding || 0)) {
                handleAmount(Number(availableOutstanding || 0));
                dispatch(confirmSlice.actions.setLoanAmount(Number(availableOutstanding || 0)));
                Alert.alert(
                    `Thông báo`,
                    `Theo quy định tại Thông tư 39/2016/TT-NHNN (được sửa đổi, bổ sung bởi Thông tư 06/2023/TT-NHNN), Dư nợ tối đa của Khách hàng vay vốn tiêu dùng phục vụ nhu cầu đời sống (thực hiện bằng phương tiện điện tử) tối đa là 100 triệu đồng. Số tiền vay tối đa của Sản phẩm mà Quý khách đang lựa chọn là ${formatMoney(
                        availableOutstanding || 0,
                    )} VND.`,
                );
            } else {
                const dataPayloadProductStatus: ProductStatusPayload['data'] = {
                    clientNo: clientNo,
                    productCode: productCode,
                    loanAmt: amount,
                };
                // để đảm bảo useEffect ko vô nhiều lần
                dispatch(confirmSlice.actions.resetAPI());

                dispatch(fetchProductStatus(dataPayloadProductStatus));
                // navigation.navigate('collateral_confirm');
            }
        }
    };

    useEffect(() => {
        const params: GetInitLoanProposalPayload['data'] = {
            clientNo: clientNo,
            depositAccounts: [account?.accountNo],
        };
        dispatch(fetchGetInitLoanProposal(params));
    }, []);

    useEffect(() => {
        if (resultCodeProductStatus === '00' && statusProductStatus === 'ON' && productStatus === true) {
            navigation.navigate('collateral_confirm');
        }
    }, [resultCodeProductStatus]);

    useEffect(() => {
        if (error) {
            Alert.alert('Thông báo', error, [
                {
                    text: 'OK',
                    onPress: () => slice.actions.setError(''),
                },
            ]);
        }
    }, [error]);

    return (
        <KeyboardAvoidingView behavior={IS_IOS ? 'padding' : 'height'} style={[css.flex_1]}>
            <ImageBackground source={getImg('/assets/images/bg_body.jpg')} resizeMode='cover' style={{ flex: 1 }}>
                <SafeAreaView style={[css.flex_1]}>
                    <SimpleHeader
                        allowGoBack
                        title={t('screen_amount.header_title')}
                        onBackPress={() => {
                            // để đảm bảo useEffect ko vô nhiều lần
                            dispatch(confirmSlice.actions.resetAPI());
                            navigation.goBack();
                        }}
                    />
                    {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
                    <ScrollView contentContainerStyle={[css.flex_1]} keyboardShouldPersistTaps='handled'>
                        <View style={[css.flex_1, css.mt_xLarge, css.mh_medium]}>
                            <Text style={[css.text_caption_100, css.font_semibold, css.text_neutral_700]}>{t('screen_amount.loan_amount')}</Text>
                            <Spacer height={4} />
                            <CurrencyInput value={amount} onValueChange={handleAmount} currency={CURRENCY} hasFocus={status !== 'loading'} />
                            <Text style={[css.text_caption_100, css.text_neutral_600, css.font_regular, css.mt_small, css.text_center]}>
                                {t('screen_amount.loan_desc', {
                                    minAmount: formatMoney(minAmount),
                                    maxAmount: formatMoney(maxAmount),
                                })}
                            </Text>
                        </View>
                        <View style={[css.mt_auto, css.p_medium]}>
                            {disabled ? (
                                <GradientButton title={t('screen_amount.submit')} gradientProps={{ type: 'secondary' }} />
                            ) : (
                                <GradientButton title={t('screen_amount.submit')} gradientProps={{ type: 'primary' }} onPress={handleSubmit} />
                            )}
                        </View>
                    </ScrollView>
                </SafeAreaView>
            </ImageBackground>
        </KeyboardAvoidingView>
    );
};

export default CollateralAmountScreen;
