import { IWeatherRepository } from '@src/domain/interfaces/weather';
import { Weather } from '../../../domain/entities/weather';
import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_LOAN_API } from '@src/config';
import { IClientInfoRepository } from '@src/domain/interfaces/common/clientInfo';
import { ClientInfo } from '@src/domain/entities/common/clientInfo';
import { GetClientInfoPayload } from '@src/application/common/get_client_info/get_client_info_payload';
import { store } from '@src/lib/redux';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class ClientInfoRepository
    extends HttpService
    implements IClientInfoRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }

    async getClientInfo<TParameter>(query: Query<TParameter>): Promise<ClientInfo> {
        const request = query.query as unknown as GetClientInfoPayload;
        const url = '/getClientInfo';
        const token = store.getState().product.token;
        try {
            const response = await this.post(url, request)
            // console.log('\x1b[31m  res ne getClientInfo', token, request, response);
            return response.data as ClientInfo;
        } catch (error) {
            throw error;
        }

    }
}
