export const formatMoney = (str: string | number | null | undefined): string => {
    return str?.toString?.()?.replace?.(/(\d)(?=(\d\d\d)+(?!\d))/g, '$1,') || ' ';
};

export const toText = (() => {
    const t: string[] = ['không', 'một', 'hai', 'ba', 'bốn', 'năm', 'sáu', 'bảy', 'tám', 'chín'];

    const r = (r: number, n: boolean): string => {
        let o: string = '';
        const a: number = Math.floor(r / 10);
        const e: number = r % 10;

        if (a > 1) {
            o = ' ' + t[a] + ' mươi';
            if (e === 1) {
                o += ' mốt';
            }
        } else if (a === 1) {
            o = ' mười';
            if (e === 1) {
                o += ' một';
            }
        } else if (n && e > 0) {
            o = ' lẻ';
        }

        if (e === 5 && a >= 1) {
            o += ' lăm';
        } else if (e === 4 && a >= 1) {
            o += ' tư';
        } else if (e > 1 || (e === 1 && a === 0)) {
            o += ' ' + t[e];
        }

        return o;
    };

    const n = (n: number, o: boolean): string => {
        let a: string = '';
        const e: number = Math.floor(n / 100);
        n = n % 100;

        if (o || e > 0) {
            a = ' ' + t[e] + ' trăm';
            a += r(n, true);
        } else {
            a = r(n, false);
        }

        return a;
    };

    const o = (t: number, r: boolean): string => {
        let o: string = '';
        let a: number = Math.floor(t / 1e6);
        t = t % 1e6;

        if (a > 0) {
            o = n(a, r) + ' triệu';
            r = true;
        }

        let e: number = Math.floor(t / 1e3);
        t = t % 1e3;

        if (e > 0) {
            o += n(e, r) + ' ngàn';
            r = true;
        }

        if (t > 0) {
            o += n(t, r);
        }

        return o;
    };

    return {
        convert: (r: number | string | undefined): string => {
            if (typeof r === 'string') r = parseFloat(r);
            if (!r) return t[0];

            let n: string = '';
            let a: string = '';
            let ty: number;

            do {
                ty = r % 1e9;
                r = Math.floor(r / 1e9);
                n = r > 0 ? o(ty, true) + a + n : o(ty, false) + a + n;
                a = ' tỷ';
            } while (r > 0);
            n = n?.trim();
            n = n?.charAt(0)?.toUpperCase() + n?.slice(1);
            return n;
        },
    };
})();

export const toTextRound = (() => {
    const t: string[] = ['không', 'một', 'hai', 'ba', 'bốn', 'năm', 'sáu', 'bảy', 'tám', 'chín'];

    return {
        convert: (r: number | string | undefined): string => {
            if (typeof r === 'string') r = parseFloat(r);
            if (!r) return t[0];

            const numStr = formatMoney(r.toString());
            if (numStr.length > 14) {
                return numStr.slice(0, 11) + '...';
            }
            // if (numStr.length >= 10) {
            //     return Math.floor(r / 1e9) + ' tỷ';
            // }

            return numStr;
        },
    };
})();
